SELECT COALESCE(SUM(amount), 0)
FROM deposit_request_details WHERE is_active = 1 AND employee_id = #{employeesId}
AND deposit_request_id IN (SELECT id FROM deposit_requests WHERE is_active = 1 AND request_date < #{date})

SELECT COALESCE(SUM(eab.amount),0)
FROM employee_adjust_beginnings AS eab
WHERE eab.is_active = 1 AND eab.date <= #{date} AND eab.employee_id = #{employeesId}

SELECT * FROM egroups WHERE is_active = 1
AND id = #{filter.groupId}
ORDER BY id ASC

SELECT IFNULL(SUM(amount),0)
FROM deposit_request_details
WHERE is_active = 1 AND status = 2 AND employee_id = #{employeesId}
AND deposit_request_id = #{depositRequestId}

mapper.sql:
WHERE leave_req.is_active = 1

  AND d.group_id = #{filter.groupId}


  AND e.department_id = #{filter.departmentId}


  AND (
  (e.is_active = 1 AND e.name LIKE CONCAT("%", #{filter.searchText}, "%")) OR
  (e.is_active = 1 AND e.name_kh LIKE CONCAT("%", #{filter.searchText}, "%")) OR
  (e.is_active = 1 AND e.code LIKE CONCAT("%", #{filter.searchText}, "%")) OR
  (e.is_active = 1 AND e.telephone LIKE CONCAT("%", #{filter.searchText}, "%"))
  )


  AND DATE(leave_req.date_from) >= #{filter.dateFrom} AND DATE(leave_req.date_from) <= #{filter.dateTo}

mapper.select:
SELECT leave_types.id AS id, leave_types.name AS name, IFNULL(SUM(leave_req.number_of_day), 0) AS numberOfDay FROM leave_types INNER JOIN employees AS e ON e.id = #{employeeId} AND e.is_active = 1 LEFT JOIN departments AS d ON d.id = e.department_id LEFT JOIN leave_requests AS leave_req ON leave_req.leave_type_id = leave_types.id AND leave_req.employee_id = e.id AND leave_req.is_active = 1
AND DATE(leave_req.date_from) >= #{filter.dateFrom} AND DATE(leave_req.date_from) <= #{filter.dateTo}
WHERE leave_types.is_active = 1 AND leave_types.id = #{leaveTypeId}
AND d.group_id = #{filter.groupId}
AND e.department_id = #{filter.departmentId}
AND ( e.name LIKE CONCAT("%", #{filter.searchText}, "%") OR e.name_kh LIKE CONCAT("%", #{filter.searchText}, "%") OR e.code LIKE CONCAT("%", #{filter.searchText}, "%") OR e.telephone LIKE CONCAT("%", #{filter.searchText}, "%") )
GROUP BY leave_types.id, leave_types.name

mapper.sql:
WHERE ea.is_active = 1

  AND ea.employee_id = #{filter.employeeId}


  AND d.id = #{filter.departmentId}


  AND p.id = #{filter.positionId}


  AND sg.id = #{filter.groupId}


  AND DATE(ea.datetime_scan) >= DATE(#{filter.dateFrom})


  AND DATE(ea.datetime_scan) <= DATE(#{filter.dateTo})


  AND (
    e.name_en LIKE CONCAT("%", #{filter.searchText}, "%") OR
    e.name_kh LIKE CONCAT("%", #{filter.searchText}, "%") OR
    e.code LIKE CONCAT("%", #{filter.searchText}, "%") OR
    e.telephone LIKE CONCAT("%", #{filter.searchText}, "%")
  )

